/* 
  Maintaining Backward Compatibility Without Versioning
  (The additive approach)
*/

// Old JSON Response (2022)
{
  "fullName": "John Doe"
}

// We realize "fullName" is bad, we want first and last separated.
// ❌ BREAKING CHANGE (Crashes old apps!)
{
  "firstName": "John",
  "lastName": "Doe"
}

// ✅ BACKWARD COMPATIBLE (Old apps read fullName, new apps read firstName)
{
  "fullName": "John Doe", // Keep this alive for old clients!
  "firstName": "John",
  "lastName": "Doe"
}
